// FileBase's marker tells readers to edit a .projenrc.js that downstream repos
// don't have, so every generated file writes this banner instead. The "~~" is
// joined at runtime so this file doesn't contain projen's marker. Otherwise
// projen's cleanup would delete this file when mxr/base synths itself.
export const BANNER = [
  "~~",
  "Generated by projen in mxr/base. Modifications will be overwritten on the next sync. To modify properly, edit .github/base.yml and retrigger the propagate workflow in mxr/base.",
].join(" ");
